h działania w samorządzie."], "risks": ["Budżety młodzieżowe działają w kilku miastach w Polsce."], "related": [], "confidence": 1.0, "version": 1, "model": "seed", "assessedAt": "2026-06-12T15:57:00+00:00"}'::jsonb, 78, 'scaling', true, 0, true, '2026-06-12T15:57:00+00:00', '2026-06-12T15:57:00+00:00') on conflict (id) do update set status_code = excluded.status_code, slug = excluded.slug, submission_kind = excluded.submission_kind, card = excluded.card, title = excluded.title, summary = excluded.summary, domains = excluded.domains, institution_type = excluded.institution_type, stage = excluded.stage, cross_topics = excluded.cross_topics, teryt = excluded.teryt, radar = excluded.radar, signal = excluded.signal, status = excluded.status, published = excluded.published, nominations_count = excluded.nominations_count, synthetic = excluded.synthetic, created_at = excluded.created_at, updated_at = excluded.updated_at;
